import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });
const cli = fileURLToPath(new URL('../job-plan.js', import.meta.url));

test('full graph ordering and current-state readiness are distinct', () => {
  assert.deepEqual(planJobs([
    job('a', ['z']), job('b'), job('z', [], 'succeeded'), job('c', ['b']),
  ]), { order: ['b', 'c', 'a'], ready: ['a', 'b'], blocked: [] });
});

test('all failed ancestors survive intermediate states and merge uniquely', () => {
  assert.deepEqual(planJobs([
    job('root', [], 'failed'), job('second', ['root'], 'failed'),
    job('ok', ['second'], 'succeeded'), job('target', ['ok', 'root']),
    job('child', ['target']),
  ]), {
    order: [], ready: [], blocked: [
      { id: 'child', causes: ['root', 'second'] },
      { id: 'target', causes: ['root', 'second'] },
    ],
  });
});

test('IDs use code-unit ordering and input remains untouched', () => {
  const ids = ['é', 'constructor', '__proto__', '😀', '\uE000', ' ', 'a', 'Z'];
  const spec = Object.freeze(ids.map(id => Object.freeze({
    ...job(id), deps: Object.freeze([]), ignored: true,
  })));
  const expected = [' ', 'Z', '__proto__', 'a', 'constructor', 'é', '😀', '\uE000'];
  assert.deepEqual(planJobs(spec), { order: expected, ready: expected, blocked: [] });
  assert.deepEqual(planJobs([job('__proto__', [], 'failed'), job('constructor', ['__proto__'])]), {
    order: [], ready: [], blocked: [{ id: 'constructor', causes: ['__proto__'] }],
  });
});

test('invalid fields, references, duplicates and completed cycles throw Errors', () => {
  const invalid = [null, {}, '[]', [null], [undefined], [new Array(3)],
    [job('')], [job(1)], [{ id: 'a', deps: [] }], [{ id: 'a', state: 'pending' }],
    [job('a', null)], [job('a', [], 'Pending')], [job('a', [], new String('pending'))],
    [job('a', [1])], [job('a', [''])], [job('a', ['missing'])],
    [job('a'), job('a')], [job('a'), job('b', ['a', 'a'])],
    [job('a', ['a'], 'succeeded')],
    [job('a', ['b'], 'failed'), job('b', ['a'], 'succeeded')],
    new Array(1), [job('a', new Array(1))],
  ];
  for (const spec of invalid) assert.throws(() => planJobs(spec), Error);
});

test('CLI emits only JSON on success, rejects errors with exit 2, and imports silently', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const file = join(dir, 'spec.json');
  const run = args => spawnSync(process.execPath, args, { encoding: 'utf8' });
  try {
    writeFileSync(file, JSON.stringify([job('é')]));
    const success = run([cli, file]);
    assert.equal(success.status, 0);
    assert.equal(success.stderr, '');
    assert.equal(success.stdout, '{"order":["é"],"ready":["é"],"blocked":[]}\n');
    for (const args of [[cli], [cli, file, file], [cli, join(dir, 'absent')]]) {
      const result = run(args);
      assert.equal(result.status, 2);
      assert.equal(result.stdout, '');
      assert.ok(result.stderr.length > 0);
    }
    for (const contents of ['{', '{}', JSON.stringify([job('a', ['a'])])]) {
      writeFileSync(file, contents);
      const result = run([cli, file]);
      assert.equal(result.status, 2);
      assert.equal(result.stdout, '');
      assert.ok(result.stderr.length > 0);
    }
    const imported = run(['--input-type=module', '-e', `import ${JSON.stringify(new URL('../job-plan.js', import.meta.url).href)}`]);
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
